pub fn set_element_type_is_concrete(elem: Rc<Node>) -> bool {
    match elem.inferred.clone() {
        Some(inf) => !is_type_variable(inf.clone()),
        None => true,
    }
}

pub fn set_element_types_mismatch(
    recv_elem: Rc<Node>,
    operand_elem: Rc<Node>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> bool {
    ((set_element_type_is_concrete(recv_elem.clone())
        && set_element_type_is_concrete(operand_elem.clone()))
        && !node_type_compatible(recv_elem.clone(), operand_elem.clone(), source_indices))
}

pub fn type_node_is_callable(n: Rc<Node>) -> bool {
    ((n.params.clone().len() as i64) > 0)
}

pub fn module_skips_direct_call_arg_check(module_name: String) -> bool {
    {
        let is_v4 = ((v1_rt::string_length(&module_name) >= 3)
            && (v1_rt::substring(&module_name, 0, 3) == "v2.".to_string()));
        let is_compiler_substrate = ((v1_rt::string_length(&module_name) >= 13)
            && (v1_rt::substring(&module_name, 0, 13) == "v1.compiler.".to_string()));
        (is_v4 || is_compiler_substrate)
    }
}

pub fn nominal_call_arg_brand_mismatch(
    formal: Rc<Node>,
    actual: Rc<Node>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> bool {
    {
        let formal_name = authored_name_at(source_indices.clone(), formal.clone());
        let actual_name = authored_name_at(source_indices.clone(), actual.clone());
        ((((((((formal.connective.clone() != Connective::Arrow)
            && (actual.connective.clone() != Connective::Arrow))
            && (formal_name.clone() != "".to_string()))
            && (actual_name.clone() != "".to_string()))
            && (formal_name.clone() != actual_name.clone()))
            && (structural_carrier_template_name(formal.clone(), source_indices.clone())
                == structural_carrier_template_name(actual.clone(), source_indices.clone())))
            && !is_declared_container_alias_spelling(formal_name.clone()))
            && !is_declared_container_alias_spelling(actual_name.clone()))
    }
}

pub fn container_element_nominal_brand_mismatch(
    formal: Rc<Node>,
    actual: Rc<Node>,
    type_env: Rc<TypeEnv>,
    module_name: String,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> bool {
    if ((node_is_element_collection(formal.clone(), source_indices.clone())
        && node_is_element_collection(actual.clone(), source_indices.clone()))
        && (authored_name_at(source_indices.clone(), formal.clone())
            == authored_name_at(source_indices.clone(), actual.clone())))
    {
        match formal.children.clone().first().cloned() {
            Some(formal_ch) => match actual.children.clone().first().cloned() {
                Some(actual_ch) => {
                    let formal_el = peel_nominal_alias_identity(
                        child_type_node(formal_ch.clone()),
                        type_env.clone(),
                        module_name.clone(),
                    );
                    let actual_el = peel_nominal_alias_identity(
                        child_type_node(actual_ch.clone()),
                        type_env.clone(),
                        module_name.clone(),
                    );
                    nominal_call_arg_brand_mismatch(formal_el, actual_el, source_indices.clone())
                }
                None => false,
            },
            None => false,
        }
    } else {
        false
    }
}

pub fn direct_call_arg_type_mismatch(
    formal: Rc<Node>,
    actual: Rc<Node>,
    type_env: Rc<TypeEnv>,
    module_name: String,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> bool {
    if (type_node_is_callable(formal.clone()) || type_node_is_callable(actual.clone())) {
        false
    } else {
        (nominal_call_arg_brand_mismatch(formal.clone(), actual.clone(), source_indices.clone())
            || container_element_nominal_brand_mismatch(
                formal.clone(),
                actual.clone(),
                type_env,
                module_name,
                source_indices.clone(),
            ))
    }
}

pub fn direct_call_arg_mismatch_diags(
    value_params: Rc<Vec<Rc<Node>>>,
    typed_args: Rc<Vec<Rc<Node>>>,
    call_subst: Rc<HashMap<String, Rc<Node>>>,
    type_env: Rc<TypeEnv>,
    module_name: String,
) -> Rc<Vec<Rc<ErrorNode>>> {
    {
        let source_indices = type_env.source_indices.clone();
        Rc::new({
            let mut __result = Vec::new();
            for pair in Rc::new(
                value_params
                    .iter()
                    .cloned()
                    .enumerate()
                    .map(|(i, v)| (i as i64, v))
                    .collect::<Vec<_>>(),
            )
            .iter()
            .cloned()
            {
                __result.extend(
                    (*{
                        let formal_raw = param_node_type_expr(pair.1.clone());
                        let formal_subst = substitute_generics(
                            formal_raw.clone(),
                            call_subst.clone(),
                            source_indices.clone(),
                        );
                        let formal = peel_nominal_alias_identity(
                            formal_subst.clone(),
                            type_env.clone(),
                            module_name.clone(),
                        );
                        match typed_args.clone().get(pair.0.clone() as usize).cloned() {
                            Some(ta) => {
                                let actual_raw = resolved_type(arg_value(ta.clone()));
                                let actual = peel_nominal_alias_identity(
                                    actual_raw.clone(),
                                    type_env.clone(),
                                    module_name.clone(),
                                );
                                if direct_call_arg_type_mismatch(
                                    formal.clone(),
                                    actual.clone(),
                                    type_env.clone(),
                                    module_name.clone(),
                                    source_indices.clone(),
                                ) {
                                    Rc::new(vec![type_mismatch_error(
                                        node_type_shape(formal.clone(), source_indices.clone()),
                                        node_type_shape(actual.clone(), source_indices.clone()),
                                        arg_value(ta.clone()).span.clone(),
                                        module_name.clone(),
                                    )])
                                } else {
                                    Rc::new(vec![])
                                }
                            }
                            None => Rc::new(vec![]),
                        }
                    })
                    .iter()
                    .cloned(),
                );
            }
            __result
        })
    }
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct Tier2bBt {
    pub bt: Rc<Node>,
    pub kernel_diags: Rc<Vec<Rc<ErrorNode>>>,
}

pub fn infer_tier2b_builtin_with_kernel_diags(
    func_name: String,
    typed_args: Rc<Vec<Rc<Node>>>,
    scope: Rc<InferScope>,
    span: Rc<SourceSpan>,
) -> Rc<Tier2bBt> {
    if ((func_name.clone() == "lookup".to_string()) || (func_name.clone() == "map_get".to_string()))
    {
        Rc::new(Tier2bBt {
            bt: match typed_args.clone().first().cloned() {
                Some(receiver_arg) => match arg_value(receiver_arg.clone())
                    .inferred
                    .clone()
                    .as_deref()
                    .cloned()
                {
                    Some(InferredNode::Resolved {
                        node: receiver_type,
                        ..
                    }) => {
                        match map_value_type_in_env(receiver_type.clone(), scope.type_env.clone()) {
                            Some(value_type) => {
                                if (func_name.clone() == "lookup".to_string()) {
                                    witness_of_element(value_type.clone())
                                } else {
                                    with_optional_cardinality(value_type.clone())
                                }
                            }
                            None => resolve_builtin_call_type(func_name.clone()),
                        }
                    }
                    _ => resolve_builtin_call_type(func_name.clone()),
                },
                None => resolve_builtin_call_type(func_name.clone()),
            },
            kernel_diags: Rc::new(vec![]),
        })
    } else {
        if (func_name.clone() == "map_keys".to_string()) {
            match typed_args.clone().first().cloned() {
                Some(receiver_arg) => match arg_value(receiver_arg.clone())
                    .inferred
                    .clone()
                    .as_deref()
                    .cloned()
                {
                    Some(InferredNode::Resolved {
                        node: receiver_type,
                        ..
                    }) => {
                        match map_key_type_in_env(receiver_type.clone(), scope.type_env.clone()) {
                            Some(key_type) => {
                                let lk = list_kernel_ty_from_element(key_type.clone());
                                Rc::new(Tier2bBt {
                                    bt: lk.ty.clone(),
                                    kernel_diags: lk.miss_diags.clone(),
                                })
                            }
                            None => Rc::new(Tier2bBt {
                                bt: resolve_builtin_call_type(func_name.clone()),
                                kernel_diags: Rc::new(vec![]),
                            }),
                        }
                    }
                    _ => Rc::new(Tier2bBt {
                        bt: resolve_builtin_call_type(func_name.clone()),
                        kernel_diags: Rc::new(vec![]),
                    }),
                },
                None => Rc::new(Tier2bBt {
                    bt: resolve_builtin_call_type(func_name.clone()),
                    kernel_diags: Rc::new(vec![]),
                }),
            }
        } else {
            if (func_name.clone() == "map_values".to_string()) {
                match typed_args.clone().first().cloned() {
                    Some(receiver_arg) => match arg_value(receiver_arg.clone())
                        .inferred
                        .clone()
                        .as_deref()
                        .cloned()
                    {
                        Some(InferredNode::Resolved {
                            node: receiver_type,
                            ..
                        }) => match map_value_type_in_env(
                            receiver_type.clone(),
                            scope.type_env.clone(),
                        ) {
                            Some(value_type) => {
                                let lv = list_kernel_ty_from_element(value_type.clone());
                                Rc::new(Tier2bBt {
                                    bt: lv.ty.clone(),
                                    kernel_diags: lv.miss_diags.clone(),
                                })
                            }
                            None => Rc::new(Tier2bBt {
                                bt: resolve_builtin_call_type(func_name.clone()),
                                kernel_diags: Rc::new(vec![]),
                            }),
                        },
                        _ => Rc::new(Tier2bBt {
                            bt: resolve_builtin_call_type(func_name.clone()),
                            kernel_diags: Rc::new(vec![]),
                        }),
                    },
                    None => Rc::new(Tier2bBt {
                        bt: resolve_builtin_call_type(func_name.clone()),
                        kernel_diags: Rc::new(vec![]),
                    }),
                }
            } else {
                if (((func_name.clone() == "set_insert".to_string())
                    || (func_name.clone() == "set_union".to_string()))
                    || (func_name.clone() == "set_contains".to_string()))
                {
                    {
                        let operand_elem = if ((func_name.clone() == "set_insert".to_string())
                            || (func_name.clone() == "set_contains".to_string()))
                        {
                            match typed_args.clone().get(1 as usize).cloned() {
                                Some(insert_arg) => match arg_value(insert_arg.clone())
                                    .inferred
                                    .clone()
                                    .as_deref()
                                    .cloned()
                                {
                                    Some(InferredNode::Resolved { node: elem, .. }) => {
                                        Some(elem.clone())
                                    }
                                    _ => None,
                                },
                                None => None,
                            }
                        } else {
                            match typed_args.clone().get(1 as usize).cloned() {
                                Some(other_arg) => match arg_value(other_arg.clone())
                                    .inferred
                                    .clone()
                                    .as_deref()
                                    .cloned()
                                {
                                    Some(InferredNode::Resolved {
                                        node: other_type, ..
                                    }) => match set_element_type_in_env(
                                        other_type.clone(),
                                        scope.type_env.clone(),
                                    ) {
                                        Some(elem_slot) => Some(child_type_node(elem_slot.clone())),
                                        None => None,
                                    },
                                    _ => None,
                                },
                                None => None,
                            }
                        };
                        let recv_is_set = match typed_args.clone().first().cloned() {
                            Some(receiver_arg) => {
                                set_builtin_receiver_is_set(receiver_arg.clone(), scope.clone())
                            }
                            None => false,
                        };
                        let union_other_bad = if (func_name.clone() == "set_union".to_string()) {
                            match typed_args.clone().get(1 as usize).cloned() {
                                Some(other_arg) => set_union_other_operand_is_resolved_non_set(
                                    other_arg.clone(),
                                    scope.clone(),
                                ),
                                None => false,
                            }
                        } else {
                            false
                        };
                        let recv_elem = match typed_args.clone().first().cloned() {
                            Some(receiver_arg) => match arg_value(receiver_arg.clone())
                                .inferred
                                .clone()
                                .as_deref()
                                .cloned()
                            {
                                Some(InferredNode::Resolved {
                                    node: receiver_type,
                                    ..
                                }) => set_element_type_from_receiver(
                                    receiver_type.clone(),
                                    scope.clone(),
                                ),
                                _ => None,
                            },
                            None => None,
                        };
                        let elem_mismatch = match recv_elem.clone() {
                            Some(re) => match operand_elem.clone() {
                                Some(oe) => set_element_types_mismatch(
                                    re.clone(),
                                    oe.clone(),
                                    scope.type_env.clone().source_indices.clone(),
                                ),
                                None => false,
                            },
                            None => false,
                        };
                        let wrong_receiver_diags = if recv_is_set.clone() {
                            Rc::new(vec![])
                        } else {
                            Rc::new(vec![inference_error(
                                v1_rt::concat(
                                    func_name.clone(),
                                    " receiver must be a Set".to_string(),
                                ),
                                span.clone(),
                                scope.module_name.clone(),
                            )])
                        };
                        let wrong_union_other_diags = if union_other_bad.clone() {
                            Rc::new(vec![inference_error(
                                "set_union second operand must be a Set".to_string(),
                                span.clone(),
                                scope.module_name.clone(),
                            )])
                        } else {
                            Rc::new(vec![])
                        };
                        let mismatch_diags = if elem_mismatch.clone() {
                            Rc::new(vec![inference_error(
                                v1_rt::concat(
                                    func_name.clone(),
                                    " incompatible set element types".to_string(),
                                ),
                                span.clone(),
                                scope.module_name.clone(),
                            )])
                        } else {
                            Rc::new(vec![])
                        };
                        let result_bt = if (func_name.clone() == "set_contains".to_string()) {
                            if (recv_is_set.clone() && !elem_mismatch.clone()) {
                                bool_type()
                            } else {
                                resolve_builtin_call_type(func_name.clone())
                            }
                        } else {
                            match typed_args.clone().first().cloned() {
                                Some(receiver_arg) => {
                                    if ((recv_is_set.clone() && !elem_mismatch.clone())
                                        && !union_other_bad.clone())
                                    {
                                        match arg_value(receiver_arg.clone())
                                            .inferred
                                            .clone()
                                            .as_deref()
                                            .cloned()
                                        {
                                            Some(InferredNode::Resolved {
                                                node: receiver_type,
                                                ..
                                            }) => match recv_elem.clone() {
                                                Some(_) => receiver_type.clone(),
                                                None => match operand_elem.clone() {
                                                    Some(element) => {
                                                        set_kernel_ty_from_element(element.clone())
                                                            .ty
                                                            .clone()
                                                    }
                                                    None => {
                                                        resolve_builtin_call_type(func_name.clone())
                                                    }
                                                },
                                            },
                                            _ => resolve_builtin_call_type(func_name.clone()),
                                        }
                                    } else {
                                        resolve_builtin_call_type(func_name.clone())
                                    }
                                }
                                None => resolve_builtin_call_type(func_name.clone()),
                            }
                        };
                        let build_diags = if (func_name.clone() == "set_contains".to_string()) {
                            Rc::new(vec![])
                        } else {
                            match operand_elem.clone() {
                                Some(element) => {
                                    if ((recv_is_set.clone() && !elem_mismatch.clone())
                                        && !union_other_bad.clone())
                                    {
                                        set_kernel_ty_from_element(element.clone())
                                            .miss_diags
                                            .clone()
                                    } else {
                                        Rc::new(vec![])
                                    }
                                }
                                None => Rc::new(vec![]),
                            }
                        };
                        Rc::new(Tier2bBt {
                            bt: result_bt,
                            kernel_diags: v1_rt::concat(
                                wrong_receiver_diags,
                                v1_rt::concat(
                                    wrong_union_other_diags,
                                    v1_rt::concat(mismatch_diags, build_diags),
                                ),
                            ),
                        })
                    }
                } else {
                    Rc::new(Tier2bBt {
                        bt: resolve_builtin_call_type(func_name.clone()),
                        kernel_diags: Rc::new(vec![]),
                    })
                }
            }
        }
    }
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct MethodPipeFallback {
    pub result_ty: Rc<Node>,
    pub kernel_diags: Rc<Vec<Rc<ErrorNode>>>,
}

pub fn method_pipe_map_keys_values_fallback(
    recv_rt: Rc<Node>,
    method_name: String,
    scope: Rc<InferScope>,
    span: Rc<SourceSpan>,
) -> Rc<MethodPipeFallback> {
    if (method_name.clone() == "map_keys".to_string()) {
        match map_key_type_in_env(recv_rt.clone(), scope.type_env.clone()) {
            Some(key_type) => {
                let lk = list_kernel_ty_from_element(key_type.clone());
                Rc::new(MethodPipeFallback {
                    result_ty: lk.ty.clone(),
                    kernel_diags: lk.miss_diags.clone(),
                })
            }
            None => Rc::new(MethodPipeFallback {
                result_ty: recv_rt.clone(),
                kernel_diags: Rc::new(vec![]),
            }),
        }
    } else {
        if (method_name.clone() == "map_values".to_string()) {
            match map_value_type_in_env(recv_rt.clone(), scope.type_env.clone()) {
                Some(value_type) => {
                    let lv = list_kernel_ty_from_element(value_type.clone());
                    Rc::new(MethodPipeFallback {
                        result_ty: lv.ty.clone(),
                        kernel_diags: lv.miss_diags.clone(),
                    })
                }
                None => Rc::new(MethodPipeFallback {
                    result_ty: recv_rt.clone(),
                    kernel_diags: Rc::new(vec![]),
                }),
            }
        } else {
            Rc::new(MethodPipeFallback {
                result_ty: recv_rt.clone(),
                kernel_diags: Rc::new(vec![]),
            })
        }
    }
}

pub fn categorized_error(
    message: String,
    span: Rc<SourceSpan>,
    module_name: String,
    category: String,
) -> Rc<ErrorNode> {
    make_error_node(
        Rc::new(CompilerDiagnostic::InternalError {
            message: message,
            span: span,
        }),
        module_name,
    )
}

pub fn validate_cast(
    source_inferred: Option<Rc<InferredNode>>,
    target_name: String,
    span: Rc<SourceSpan>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
    module_name: String,
) -> Option<Rc<ErrorNode>> {
    match source_inferred.as_deref().cloned() {
        Some(InferredNode::Resolved { node: src_node, .. }) => {
            let source_name = authored_name_at(source_indices, src_node.clone());
            if (source_name.clone() == target_name.clone()) {
                None
            } else {
                if !is_dag_cast_domain_type(source_name.clone()) {
                    None
                } else {
                    if !is_dag_cast_domain_type(target_name.clone()) {
                        None
                    } else {
                        if dag_can_cast(source_name.clone(), target_name.clone()) {
                            None
                        } else {
                            {
                                let msg = v1_rt::concat(
                                    v1_rt::concat(
                                        v1_rt::concat(
                                            "invalid cast: ".to_string(),
                                            source_name.clone(),
                                        ),
                                        " as ".to_string(),
                                    ),
                                    target_name.clone(),
                                );
                                let diag = Rc::new(CompilerDiagnostic::InternalError {
                                    message: msg,
                                    span: span,
                                });
                                Some(make_error_node(diag, module_name))
                            }
                        }
                    }
                }
            }
        }
        _ => None,
    }
}

