pub fn resolve_env_bindings(
    env: Rc<TypeEnv>,
    module_name: String,
    local_names: Rc<HashMap<i64, bool>>,
    deps_map: Rc<HashMap<String, Rc<Vec<String>>>>,
) -> Rc<EnvResolveResult> {
    {
        let remaining = Rc::new({
            let mut __result = Vec::new();
            for b in Rc::new({
                let mut __result = Vec::new();
                for b in Rc::new(v1_rt::map_values(&env.bindings.clone()))
                    .iter()
                    .cloned()
                {
                    if v1_rt::map_contains_key(
                        &local_names,
                        intern(env.intern_table.clone(), b.name.clone()).id.clone(),
                    ) {
                        __result.push(b);
                    }
                }
                __result
            })
            .iter()
            .cloned()
            {
                __result.push(b.name.clone());
            }
            __result
        });
        topo_resolve_types(
            remaining.clone(),
            env.clone(),
            module_name,
            Rc::new(vec![]),
            local_names.clone(),
            deps_map,
            (remaining.clone().len() as i64),
        )
    }
}

pub fn topo_resolve_types(
    mut remaining: Rc<Vec<String>>,
    mut env: Rc<TypeEnv>,
    mut module_name: String,
    mut diagnostics: Rc<Vec<Rc<ErrorNode>>>,
    mut local_names: Rc<HashMap<i64, bool>>,
    mut deps_map: Rc<HashMap<String, Rc<Vec<String>>>>,
    mut fuel: i64,
) -> Rc<EnvResolveResult> {
    loop {
        if ((remaining.clone().len() as i64) == 0) {
            return Rc::new(EnvResolveResult {
                env: env.clone(),
                diagnostics: diagnostics.clone(),
            });
        }
        let remaining_set = remaining
            .clone()
            .iter()
            .cloned()
            .fold(v1_rt::rc_empty_set::<_>(), |acc: _, name: String| {
                v1_rt::rc_set_insert(acc, name.clone())
            });
        let ready = Rc::new({
            let mut __result = Vec::new();
            for name in remaining.clone().iter().cloned() {
                if match v1_rt::map_get(&deps_map, name.clone()) {
                    Some(deps) => {
                        let mut __all = true;
                        for dep in deps.clone().iter().cloned() {
                            if !((((is_kernel_type(dep.clone())
                                || (dep.clone() == "None".to_string()))
                                || (dep.clone() == "".to_string()))
                                || is_recursive_type_by_name(env.clone(), dep.clone()))
                                || (v1_rt::set_contains(&remaining_set, dep.clone()) == false))
                            {
                                __all = false;
                                break;
                            }
                        }
                        __all
                    }
                    None => true,
                } {
                    __result.push(name);
                }
            }
            __result
        });
        if ((ready.clone().len() as i64) == 0) {
            {
                let stuck_accum = remaining.clone().iter().cloned().fold(
                    Rc::new(BindingsAccum {
                        bindings: env.bindings.clone(),
                        str_bindings: env.str_bindings.clone(),
                        diagnostics: Rc::new(vec![]),
                    }),
                    |acc: Rc<BindingsAccum>, name: String| {
                        let ident = intern(env.intern_table.clone(), name.clone()).id.clone();
                        match v1_rt::map_get(&env.bindings.clone(), ident.clone()) {
                            Some(binding) => {
                                let pre = binding.resolved.clone();
                                let result =
                                    resolve_node(pre.clone(), env.clone(), module_name.clone());
                                let resolved = preserve_nominal_brand_on_resolve(
                                    pre.clone(),
                                    result.resolved.clone(),
                                    binding.name.clone(),
                                    env.source_indices.clone(),
                                );
                                let updated_binding = Rc::new(TypeBinding {
                                    name: name.clone(),
                                    resolved: resolved.clone(),
                                    provenance: Rc::new(SubValueRelation::SubValueUnknown),
                                });
                                Rc::new(BindingsAccum {
                                    bindings: v1_rt::rc_map_insert(
                                        acc.bindings.clone(),
                                        ident.clone(),
                                        updated_binding.clone(),
                                    ),
                                    str_bindings: v1_rt::rc_map_insert(
                                        acc.str_bindings.clone(),
                                        name.clone(),
                                        updated_binding,
                                    ),
                                    diagnostics: v1_rt::concat(
                                        acc.diagnostics.clone(),
                                        result.diagnostics.clone(),
                                    ),
                                })
                            }
                            None => acc.clone(),
                        }
                    },
                );
                return Rc::new(EnvResolveResult {
                    env: Rc::new(TypeEnv {
                        bindings: stuck_accum.bindings.clone(),
                        str_bindings: stuck_accum.str_bindings.clone(),
                        ancestry_str_bindings: env.ancestry_str_bindings.clone(),
                        parents: env.parents.clone(),
                        recursive_types: env.recursive_types.clone(),
                        recursive_type_set: env.recursive_type_set.clone(),
                        inductive_fields: env.inductive_fields.clone(),
                        source_indices: env.source_indices.clone(),
                        intern_table: env.intern_table.clone(),
                    }),
                    diagnostics: v1_rt::concat(
                        diagnostics.clone(),
                        stuck_accum.diagnostics.clone(),
                    ),
                });
            }
        }
        let ready_accum = ready.clone().iter().cloned().fold(
            Rc::new(BindingsAccum {
                bindings: env.bindings.clone(),
                str_bindings: env.str_bindings.clone(),
                diagnostics: Rc::new(vec![]),
            }),
            |acc: Rc<BindingsAccum>, name: String| {
                let ident = intern(env.intern_table.clone(), name.clone()).id.clone();
                match v1_rt::map_get(&env.bindings.clone(), ident.clone()) {
                    Some(binding) => {
                        let pre = binding.resolved.clone();
                        let result = resolve_node(pre.clone(), env.clone(), module_name.clone());
                        let resolved = preserve_nominal_brand_on_resolve(
                            pre.clone(),
                            result.resolved.clone(),
                            binding.name.clone(),
                            env.source_indices.clone(),
                        );
                        let updated_binding = Rc::new(TypeBinding {
                            name: name.clone(),
                            resolved: resolved.clone(),
                            provenance: Rc::new(SubValueRelation::SubValueUnknown),
                        });
                        Rc::new(BindingsAccum {
                            bindings: v1_rt::rc_map_insert(
                                acc.bindings.clone(),
                                ident.clone(),
                                updated_binding.clone(),
                            ),
                            str_bindings: v1_rt::rc_map_insert(
                                acc.str_bindings.clone(),
                                name.clone(),
                                updated_binding,
                            ),
                            diagnostics: v1_rt::concat(
                                acc.diagnostics.clone(),
                                result.diagnostics.clone(),
                            ),
                        })
                    }
                    None => acc.clone(),
                }
            },
        );
        let ready_set = ready.clone().iter().cloned().fold(
            v1_rt::rc_empty_map::<String, bool>(),
            |acc: Rc<HashMap<String, bool>>, name: String| {
                v1_rt::rc_map_insert(acc, name.clone(), true)
            },
        );
        let next_remaining = Rc::new({
            let mut __result = Vec::new();
            for name in remaining.clone().iter().cloned() {
                if (emit_map_has(ready_set.clone(), name.clone()) == false) {
                    __result.push(name);
                }
            }
            __result
        });
        {
            let __tco_0 = next_remaining;
            let __tco_1 = Rc::new(TypeEnv {
                bindings: ready_accum.bindings.clone(),
                str_bindings: ready_accum.str_bindings.clone(),
                ancestry_str_bindings: env.ancestry_str_bindings.clone(),
                parents: env.parents.clone(),
                recursive_types: env.recursive_types.clone(),
                recursive_type_set: env.recursive_type_set.clone(),
                inductive_fields: env.inductive_fields.clone(),
                source_indices: env.source_indices.clone(),
                intern_table: env.intern_table.clone(),
            });
            let __tco_2 = v1_rt::concat(diagnostics, ready_accum.diagnostics.clone());
            let __tco_3 = (fuel - 1);
            remaining = __tco_0;
            env = __tco_1;
            diagnostics = __tco_2;
            fuel = __tco_3;
            continue;
        }
    }
}

pub fn collect_parent_envs(
    resolved: Rc<ResolvedModule>,
    module_index: Rc<HashMap<String, Rc<TypedModule>>>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> Rc<ParentModulesResult> {
    {
        let modules = Rc::new({
            let mut __result = Vec::new();
            for imp in resolved.resolved_imports.clone().iter().cloned() {
                __result.extend(
                    (*match v1_rt::map_get(&module_index, imp.module_path.clone()) {
                        Some(typed) => Rc::new(vec![typed.clone()]),
                        None => Rc::new(vec![]),
                    })
                    .iter()
                    .cloned(),
                );
            }
            __result
        });
        let resolved_mod_name = authored_name_at(source_indices, resolved.module.clone());
        let diagnostics = Rc::new({
            let mut __result = Vec::new();
            for imp in resolved.resolved_imports.clone().iter().cloned() {
                __result.extend(
                    (*match v1_rt::map_get(&module_index, imp.module_path.clone()) {
                        Some(_) => Rc::new(vec![]),
                        None => Rc::new(vec![make_error_node(
                            Rc::new(CompilerDiagnostic::InternalError {
                                message: v1_rt::concat(
                                    v1_rt::concat(
                                        v1_rt::concat(
                                            v1_rt::concat(
                                                "missing parent environment for imported module '"
                                                    .to_string(),
                                                imp.module_path.clone(),
                                            ),
                                            "' while ordering '".to_string(),
                                        ),
                                        resolved_mod_name.clone(),
                                    ),
                                    "'".to_string(),
                                ),
                                span: imp.target_module.clone().clone().unwrap().span.clone(),
                            }),
                            resolved_mod_name.clone(),
                        )]),
                    })
                    .iter()
                    .cloned(),
                );
            }
            __result
        });
        Rc::new(ParentModulesResult {
            modules: modules,
            diagnostics: diagnostics,
        })
    }
}

pub fn variant_has_positional_payload_shape(
    variant: Rc<Node>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> bool {
    (((variant.children.clone().len() as i64) == 1)
        && match variant.children.clone().first().cloned() {
            Some(f) => (field_node_name_at(f.clone(), source_indices) == "0".to_string()),
            None => false,
        })
}

pub fn build_fielded_variants(
    modules: Rc<Vec<Rc<TypedModule>>>,
    type_summaries: Rc<HashMap<String, Rc<TypeSummary>>>,
) -> Rc<std::collections::BTreeSet<String>> {
    {
        let result = modules.iter().cloned().fold(
            v1_rt::rc_empty_set::<_>(),
            |acc: _, m: Rc<TypedModule>| {
                let items = m.items.clone();
                let si = m.type_env.clone().source_indices.clone();
                items
                    .clone()
                    .iter()
                    .cloned()
                    .fold(acc, |inner: _, item: Rc<Node>| {
                        let is_enum = match v1_rt::map_get(
                            &type_summaries,
                            authored_name_at(si.clone(), item.clone()),
                        ) {
                            Some(summary) => match (*summary.repr.clone()).clone() {
                                TypeRepr::EnumRepr { unit_only: _, .. } => true,
                                _ => false,
                            },
                            None => false,
                        };
                        if is_enum.clone() {
                            {
                                let enum_name = authored_name_at(si.clone(), item.clone());
                                let variants = item.children.clone();
                                variants.clone().iter().cloned().fold(
                                    inner.clone(),
                                    |vacc: _, variant: Rc<Node>| {
                                        let has_fields =
                                            ((variant.children.clone().len() as i64) > 0);
                                        let is_positional_payload =
                                            variant_has_positional_payload_shape(
                                                variant.clone(),
                                                si.clone(),
                                            );
                                        if (has_fields.clone() && !is_positional_payload.clone()) {
                                            v1_rt::rc_set_insert(
                                                vacc.clone(),
                                                v1_rt::concat(
                                                    v1_rt::concat(
                                                        enum_name.clone(),
                                                        "::".to_string(),
                                                    ),
                                                    authored_name_at(si.clone(), variant.clone()),
                                                ),
                                            )
                                        } else {
                                            vacc.clone()
                                        }
                                    },
                                )
                            }
                        } else {
                            inner.clone()
                        }
                    })
            },
        );
        result
    }
}

pub fn build_positional_payload_variants(
    modules: Rc<Vec<Rc<TypedModule>>>,
    type_summaries: Rc<HashMap<String, Rc<TypeSummary>>>,
) -> Rc<std::collections::BTreeSet<String>> {
    modules.iter().cloned().fold(
        v1_rt::rc_empty_set::<String>(),
        |acc: Rc<std::collections::BTreeSet<String>>, m: Rc<TypedModule>| {
            let items = m.items.clone();
            let si = m.type_env.clone().source_indices.clone();
            items.clone().iter().cloned().fold(
                acc,
                |inner: Rc<std::collections::BTreeSet<String>>, item: Rc<Node>| {
                    let is_enum = match v1_rt::map_get(
                        &type_summaries,
                        authored_name_at(si.clone(), item.clone()),
                    ) {
                        Some(summary) => match (*summary.repr.clone()).clone() {
                            TypeRepr::EnumRepr { unit_only: _, .. } => true,
                            _ => false,
                        },
                        None => false,
                    };
                    if is_enum.clone() {
                        {
                            let enum_name = authored_name_at(si.clone(), item.clone());
                            let variants = item.children.clone();
                            variants.clone().iter().cloned().fold(
                                inner.clone(),
                                |vacc: Rc<std::collections::BTreeSet<String>>,
                                 variant: Rc<Node>| {
                                    if variant_has_positional_payload_shape(
                                        variant.clone(),
                                        si.clone(),
                                    ) {
                                        v1_rt::rc_set_insert(
                                            vacc.clone(),
                                            v1_rt::concat(
                                                v1_rt::concat(enum_name.clone(), "::".to_string()),
                                                authored_name_at(si.clone(), variant.clone()),
                                            ),
                                        )
                                    } else {
                                        vacc.clone()
                                    }
                                },
                            )
                        }
                    } else {
                        inner.clone()
                    }
                },
            )
        },
    )
}

pub fn rust_corpus_repr(modules: Rc<Vec<Rc<TypedModule>>>) -> RustCorpusRepr {
    {
        let has_seed = {
            let mut __found = false;
            for m in modules.iter().cloned() {
                if {
                    let mut __found = false;
                    for k in Rc::new(v1_rt::map_keys(&m.type_env.clone().source_indices.clone()))
                        .iter()
                        .cloned()
                    {
                        if (v1_rt::contains(k.clone(), "/v1/".to_string())
                            || v1_rt::contains(k.clone(), "src/v1".to_string()))
                        {
                            __found = true;
                            break;
                        }
                    }
                    __found
                } {
                    __found = true;
                    break;
                }
            }
            __found
        };
        if has_seed {
            RustCorpusRepr::HostNative
        } else {
            RustCorpusRepr::FaithfulFreeMonoid
        }
    }
}

pub fn build_emit_graph_info(modules: Rc<Vec<Rc<TypedModule>>>) -> Rc<EmitGraphInfo> {
    {
        let init = Rc::new(EmitInfoBuildState {
            type_summaries: v1_rt::rc_empty_map::<String, Rc<TypeSummary>>(),
        });
        let built_raw = modules.clone().iter().cloned().fold(
            init.clone(),
            |state: Rc<EmitInfoBuildState>, typed_module: Rc<TypedModule>| {
                typed_module.items.clone().iter().cloned().fold(
                    state,
                    |inner_state: Rc<EmitInfoBuildState>, item: Rc<Node>| {
                        add_emit_item_summary(
                            inner_state,
                            item.clone(),
                            typed_module.type_env.clone().source_indices.clone(),
                        )
                    },
                )
            },
        );
        let built = Rc::new(EmitInfoBuildState {
            type_summaries: close_fn_fields(built_raw.type_summaries.clone()),
        });
        let all_recursive = modules.clone().iter().cloned().fold(
            v1_rt::rc_empty_set::<_>(),
            |acc: _, m: Rc<TypedModule>| {
                Rc::new(v1_rt::map_keys(
                    &m.type_env.clone().recursive_type_set.clone(),
                ))
                .iter()
                .cloned()
                .fold(acc, |inner: _, ident: i64| {
                    v1_rt::rc_set_insert(
                        inner,
                        intern_str(m.type_env.clone().intern_table.clone(), ident.clone()),
                    )
                })
            },
        );
        let fielded = build_fielded_variants(modules.clone(), built.type_summaries.clone());
        let positional =
            build_positional_payload_variants(modules.clone(), built.type_summaries.clone());
        let vtoe = derive_variant_to_enum(built.type_summaries.clone());
        Rc::new(EmitGraphInfo {
            type_summaries: built.type_summaries.clone(),
            recursive_type_set: all_recursive,
            fielded_variants: fielded,
            positional_payload_variants: positional,
            shared_types: v1_rt::rc_empty_set::<String>(),
            ownership_index: v1_rt::rc_empty_map::<String, Rc<std::collections::BTreeSet<String>>>(
            ),
            movable: v1_rt::rc_empty_set::<String>(),
            variant_to_enum: vtoe,
            owned_bindings: v1_rt::rc_empty_set::<String>(),
            read_only_params_index: v1_rt::rc_empty_map::<
                String,
                Rc<std::collections::BTreeSet<String>>,
            >(),
            read_only_params: v1_rt::rc_empty_set::<String>(),
            corpus_repr: rust_corpus_repr(modules.clone()),
        })
    }
}

pub fn seed_kernel_intern_table(intern_table: Rc<InternTable>) -> Rc<InternTable> {
    {
        let intern_table = Rc::new(v1_rt::map_keys(&kernel_type_set()))
            .iter()
            .cloned()
            .fold(intern_table.clone(), |t: Rc<InternTable>, name: String| {
                intern(t, name.clone()).table.clone()
            });
        let intern_table = Rc::new(vec![
            "Optional".to_string(),
            "Present".to_string(),
            "Absent".to_string(),
            "value".to_string(),
            "none".to_string(),
        ])
        .iter()
        .cloned()
        .fold(intern_table.clone(), |t: Rc<InternTable>, name: String| {
            intern(t, name.clone()).table.clone()
        });
        Rc::new(v1_rt::map_keys(&compiler_recursive_types()))
            .iter()
            .cloned()
            .fold(intern_table.clone(), |t: Rc<InternTable>, name: String| {
                intern(t, name.clone()).table.clone()
            })
    }
}

pub fn typecheck(
    graph: Rc<ModuleGraph>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
    intern_table: Rc<InternTable>,
) -> Rc<TypedGraph> {
    {
        let intern_table = seed_kernel_intern_table(intern_table.clone());
        typecheck_modules(
            graph.modules.clone(),
            Rc::new(vec![]),
            v1_rt::rc_empty_map::<String, Rc<TypedModule>>(),
            v1_rt::rc_empty_map::<String, Rc<VariantExportSurface>>(),
            v1_rt::rc_empty_map::<String, Rc<ItemInfo>>(),
            Rc::new(vec![]),
            source_indices,
            intern_table.clone(),
        )
    }
}

pub fn typecheck_modules(
    mut remaining: Rc<Vec<Rc<ResolvedModule>>>,
    mut modules: Rc<Vec<Rc<TypedModule>>>,
    mut module_index: Rc<HashMap<String, Rc<TypedModule>>>,
    mut variant_surfaces: Rc<HashMap<String, Rc<VariantExportSurface>>>,
    mut item_registry: Rc<HashMap<String, Rc<ItemInfo>>>,
    mut diag_chunks: Rc<Vec<Rc<Vec<Rc<ErrorNode>>>>>,
    mut source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
    mut intern_table: Rc<InternTable>,
) -> Rc<TypedGraph> {
    loop {
        match remaining.clone().first().cloned() {
            None => {
                let expanded_registry =
                    expand_transitive_services(modules.clone(), item_registry, 5);
                break Rc::new(TypedGraph {
                    modules: modules.clone(),
                    item_registry: expanded_registry,
                    diagnostics: Rc::new({
                        let mut __result = Vec::new();
                        for c in diag_chunks.iter().cloned() {
                            __result.extend((*c.clone()).iter().cloned());
                        }
                        __result
                    }),
                });
            }
            Some(resolved) => {
                let parent_result = collect_parent_envs(
                    resolved.clone(),
                    module_index.clone(),
                    source_indices.clone(),
                );
                let tc_result = typecheck_module(
                    resolved.clone(),
                    module_index.clone(),
                    variant_surfaces.clone(),
                    source_indices.clone(),
                    intern_table.clone(),
                );
                let typed = tc_result.typed.clone();
                let tc_diags = tc_result.diagnostics.clone();
                let typed_path = authored_name_at(source_indices.clone(), typed.module.clone());
                variant_surfaces = v1_rt::rc_map_insert(
                    variant_surfaces.clone(),
                    typed_path.clone(),
                    build_variant_export_surface(
                        typed.clone(),
                        variant_surfaces.clone(),
                        source_indices.clone(),
                    ),
                );
                {
                    let __tco_0 = Rc::new(
                        remaining
                            .iter()
                            .cloned()
                            .skip(1 as usize)
                            .collect::<Vec<_>>(),
                    );
                    let __tco_1 = v1_rt::rc_list_push(modules, typed.clone());
                    let __tco_2 = v1_rt::rc_map_insert(module_index, typed_path, typed.clone());
                    let __tco_3 = v1_rt::rc_map_merge(item_registry, typed.item_registry.clone());
                    let __tco_4 = v1_rt::rc_list_push(
                        v1_rt::rc_list_push(diag_chunks, parent_result.diagnostics.clone()),
                        tc_diags,
                    );
                    remaining = __tco_0;
                    modules = __tco_1;
                    module_index = __tco_2;
                    item_registry = __tco_3;
                    diag_chunks = __tco_4;
                    continue;
                }
            }
        }
    }
}

pub fn import_module_path_at(
    imp: Rc<Node>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> String {
    authored_name_at(source_indices, imp)
}

pub fn build_type_name_export_index(
    modules: Rc<Vec<Rc<TypedModule>>>,
) -> Rc<HashMap<String, Rc<TypeNameExportFacts>>> {
    modules.iter().cloned().fold(
        v1_rt::rc_empty_map::<String, Rc<TypeNameExportFacts>>(),
        |acc: Rc<HashMap<String, Rc<TypeNameExportFacts>>>, m: Rc<TypedModule>| {
            let mut seen_names = std::collections::HashSet::<String>::new();
            m.type_env
                .bindings
                .values()
                .cloned()
                .fold(acc, |acc2, binding| {
                    let name = binding.name.clone();
                    if !seen_names.insert(name.clone()) {
                        return acc2;
                    }
                    let canonical = m
                        .type_env
                        .bindings
                        .values()
                        .filter(|b| b.name == name)
                        .next()
                        .cloned()
                        .unwrap_or(binding);
                    match v1_rt::map_get(&acc2, name.clone()) {
                        None => v1_rt::rc_map_insert(
                            acc2,
                            name,
                            Rc::new(TypeNameExportFacts {
                                exporter_count: 1,
                                canonical_binding: Some(canonical),
                            }),
                        ),
                        Some(facts) => v1_rt::rc_map_insert(
                            acc2,
                            name,
                            Rc::new(TypeNameExportFacts {
                                exporter_count: facts.exporter_count + 1,
                                canonical_binding: Some(canonical),
                            }),
                        ),
                    }
                })
        },
    )
}

pub fn rewire_type_env_import_str_binding_identity(
    modules: Rc<Vec<Rc<TypedModule>>>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> Rc<Vec<Rc<TypedModule>>> {
    record_rewire_type_env_import_str_binding_call();

    fn module_exports_type_name(m: Rc<TypedModule>, name: &str) -> bool {
        m.type_env
            .bindings
            .values()
            .any(|b| b.name.as_str() == name)
    }

    fn direct_import_exporter_count(
        m: Rc<TypedModule>,
        name: &str,
        index: &HashMap<String, Rc<TypedModule>>,
        source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
    ) -> usize {
        module_imports(m.module.clone())
            .iter()
            .filter(|imp| {
                let path = import_module_path_at((*imp).clone(), source_indices.clone());
                index.get(&path).map_or(false, |parent| {
                    module_exports_type_name(parent.clone(), name)
                })
            })
            .count()
    }

    let type_name_index = build_type_name_export_index(modules.clone());
    let index = modules.clone().iter().cloned().fold(
        v1_rt::rc_empty_map::<String, Rc<TypedModule>>(),
        |acc: Rc<HashMap<String, Rc<TypedModule>>>, m: Rc<TypedModule>| {
            v1_rt::rc_map_insert(
                acc,
                authored_name_at(source_indices.clone(), m.module.clone()),
                m.clone(),
            )
        },
    );

    Rc::new({
        let mut __result = Vec::new();
        for m in modules.clone().iter().cloned() {
            let local_names: std::collections::HashSet<String> = m
                .type_env
                .bindings
                .values()
                .map(|b| b.name.clone())
                .collect();
            let mut str_bindings = m.type_env.str_bindings.clone();
            let mut ancestry_str_bindings = m.type_env.ancestry_str_bindings.clone();
            let mut inherited_names: Vec<String> = Rc::new(v1_rt::map_keys(&ancestry_str_bindings))
                .iter()
                .chain(Rc::new(v1_rt::map_keys(&str_bindings)).iter())
                .cloned()
                .filter(|name| !local_names.contains(name))
                .collect();
            inherited_names.sort();
            for name in inherited_names {
                let exporter_count = v1_rt::map_get(&type_name_index, name.clone())
                    .map(|facts| facts.exporter_count)
                    .unwrap_or(0);
                if direct_import_exporter_count(
                    m.clone(),
                    name.as_str(),
                    &index,
                    source_indices.clone(),
                ) > 1
                    || exporter_count > 1
                {
                    continue;
                }
                if let Some(facts) = v1_rt::map_get(&type_name_index, name.clone()) {
                    if let Some(canonical) = facts.canonical_binding.clone() {
                        if match v1_rt::map_get(&ancestry_str_bindings, name.clone()) {
                            Some(existing) => {
                                Rc::ptr_eq(&existing.resolved, &canonical.resolved)
                                    && existing.name == canonical.name
                            }
                            None => false,
                        } {
                            continue;
                        }
                        ancestry_str_bindings = v1_rt::rc_map_insert(
                            ancestry_str_bindings,
                            name.clone(),
                            canonical.clone(),
                        );
                        if v1_rt::map_contains_key(&str_bindings, name.clone()) {
                            str_bindings =
                                v1_rt::rc_map_insert(str_bindings, name.clone(), canonical);
                        }
                    }
                }
            }
            __result.push(Rc::new(TypedModule {
                module: m.module.clone(),
                items: m.items.clone(),
                type_env: Rc::new(TypeEnv {
                    bindings: m.type_env.bindings.clone(),
                    str_bindings,
                    ancestry_str_bindings,
                    parents: m.type_env.parents.clone(),
                    recursive_types: m.type_env.recursive_types.clone(),
                    recursive_type_set: m.type_env.recursive_type_set.clone(),
                    inductive_fields: m.type_env.inductive_fields.clone(),
                    source_indices: m.type_env.source_indices.clone(),
                    intern_table: m.type_env.intern_table.clone(),
                }),
                type_env_cache: m.type_env_cache.clone(),
                func_env: m.func_env.clone(),
                item_registry: m.item_registry.clone(),
            }));
        }
        __result
    })
}

pub fn rewire_type_env_parent_links(
    modules: Rc<Vec<Rc<TypedModule>>>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> Rc<Vec<Rc<TypedModule>>> {
    record_rewire_type_env_parent_links_call();
    {
        let intern_table = modules
            .first()
            .map(|m| m.type_env.intern_table.clone())
            .unwrap_or_else(empty_intern_table);
        let shared_kernel = modules
            .iter()
            .find_map(|m| {
                m.type_env.parents.last().and_then(|kernel| {
                    if kernel.bindings.is_empty() {
                        None
                    } else {
                        Some(kernel.clone())
                    }
                })
            })
            .unwrap_or_else(|| {
                compiler_kernel_type_env(source_indices.clone(), intern_table.clone())
            });
        let index = modules.clone().iter().cloned().fold(
            v1_rt::rc_empty_map::<String, Rc<TypedModule>>(),
            |acc: Rc<HashMap<String, Rc<TypedModule>>>, m: Rc<TypedModule>| {
                v1_rt::rc_map_insert(
                    acc,
                    authored_name_at(source_indices.clone(), m.module.clone()),
                    m.clone(),
                )
            },
        );
        Rc::new({
            let mut __result = Vec::new();
            for m in modules.clone().iter().cloned() {
                __result.push({
                    let import_parents = Rc::new({
                        let mut __result = Vec::new();
                        for imp in module_imports(m.module.clone()).iter().cloned() {
                            __result.extend(
                                (*{
                                    let path =
                                        import_module_path_at(imp.clone(), source_indices.clone());
                                    match v1_rt::map_get(&index, path.clone()) {
                                        Some(parent) => Rc::new(vec![type_env_for_import(
                                            path.clone(),
                                            parent.type_env.clone(),
                                        )]),
                                        None => Rc::new(vec![]),
                                    }
                                })
                                .iter()
                                .cloned(),
                            );
                        }
                        __result
                    });
                    let kernel_parent = Rc::new(vec![shared_kernel.clone()]);
                    Rc::new(TypedModule {
                        module: m.module.clone(),
                        items: m.items.clone(),
                        type_env: Rc::new(TypeEnv {
                            bindings: m.type_env.clone().bindings.clone(),
                            str_bindings: m.type_env.clone().str_bindings.clone(),
                            ancestry_str_bindings: m.type_env.clone().ancestry_str_bindings.clone(),
                            parents: v1_rt::concat(import_parents.clone(), kernel_parent.clone()),
                            recursive_types: m.type_env.clone().recursive_types.clone(),
                            recursive_type_set: m.type_env.clone().recursive_type_set.clone(),
                            inductive_fields: m.type_env.clone().inductive_fields.clone(),
                            source_indices: m.type_env.clone().source_indices.clone(),
                            intern_table: m.type_env.clone().intern_table.clone(),
                        }),
                        type_env_cache: m.type_env_cache.clone(),
                        func_env: m.func_env.clone(),
                        item_registry: m.item_registry.clone(),
                    })
                });
            }
            __result
        })
    }
}

pub fn rewire_func_env_parent_links(
    modules: Rc<Vec<Rc<TypedModule>>>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> Rc<Vec<Rc<TypedModule>>> {
    {
        let index = modules.clone().iter().cloned().fold(
            v1_rt::rc_empty_map::<String, Rc<TypedModule>>(),
            |acc: Rc<HashMap<String, Rc<TypedModule>>>, m: Rc<TypedModule>| {
                v1_rt::rc_map_insert(
                    acc,
                    authored_name_at(source_indices.clone(), m.module.clone()),
                    m.clone(),
                )
            },
        );
        Rc::new({
            let mut __result = Vec::new();
            for m in modules.clone().iter().cloned() {
                __result.push({
                    let parents = Rc::new({
                        let mut __result = Vec::new();
                        for imp in module_imports(m.module.clone()).iter().cloned() {
                            __result.extend(
                                (*{
                                    let path =
                                        import_module_path_at(imp.clone(), source_indices.clone());
                                    match v1_rt::map_get(&index, path.clone()) {
                                        Some(parent) => Rc::new(vec![parent.func_env.clone()]),
                                        None => Rc::new(vec![]),
                                    }
                                })
                                .iter()
                                .cloned(),
                            );
                        }
                        __result
                    });
                    Rc::new(TypedModule {
                        module: m.module.clone(),
                        items: m.items.clone(),
                        type_env: m.type_env.clone(),
                        type_env_cache: m.type_env_cache.clone(),
                        func_env: Rc::new(ResolvedFuncEnv {
                            local: m.func_env.clone().local.clone(),
                            parents: parents.clone(),
                        }),
                        item_registry: m.item_registry.clone(),
                    })
                });
            }
            __result
        })
    }
}

pub fn reconcile(
    graph: Rc<ModuleGraph>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
    intern_table: Rc<InternTable>,
) -> Rc<ResolvedGraph> {
    {
        let typed = typecheck(graph, source_indices.clone(), intern_table);
        let modules = rewire_type_env_parent_links(typed.modules.clone(), source_indices.clone());
        let modules =
            rewire_type_env_import_str_binding_identity(modules.clone(), source_indices.clone());
        let modules = rewire_func_env_parent_links(modules.clone(), source_indices.clone());
        let emit_info = build_emit_graph_info(modules.clone());
        Rc::new(ResolvedGraph {
            modules: modules.clone(),
            item_registry: typed.item_registry.clone(),
            diagnostics: typed.diagnostics.clone(),
            emit_graph_info: emit_info,
        })
    }
}
